function incremovableSubarrayCount(nums) {
  const n = nums.length;
  let left = 0;
  while (left + 1 < n && nums[left] < nums[left + 1]) {
    left++;
  }
  if (left === n - 1) {
    return n * (n + 1) / 2;
  }

  let count = left + 2;
  for (let right = n - 1; right > 0; right--) {
    if (right < n - 1 && nums[right] >= nums[right + 1]) {
      break;
    }
    while (left >= 0 && nums[left] >= nums[right]) {
      left--;
    }
    count += left + 2;
  }
  return count;
}

