  // Delete every subarray [start, end] and test what is left.
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      const rest = nums.slice(0, start).concat(nums.slice(end + 1));
      let increasing = true;
      for (let i = 1; i < rest.length; i++) if (rest[i - 1] >= rest[i]) increasing = false;
      if (increasing) total++;
    }
  }
  return total;
}

