function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 9);
  const mode = rand();
  if (!large && mode < 0.3) return [Array.from({ length: n }, () => int(1, 6))];
  // An increasing run, a random middle and another increasing run, so the answer is far from trivial.
  const climb = (length, start, step) => {
    const run = [];
    let value = start;
    for (let i = 0; i < length; i++) { value += int(1, step); run.push(value); }
    return run;
  };
  const step = large ? 400000 : 3;
  const head = mode < 0.45 ? n : int(0, n);
  const tail = int(0, n - head);
  const middle = Array.from({ length: n - head - tail }, () => int(1, large ? 1000000000 : 20));
  const nums = [...climb(head, int(0, large ? 1000000 : 4), step), ...middle, ...climb(tail, int(0, large ? 1000000 : 4), step)];
  return [nums];
}
